using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public class ImportTraderBounty085 {public static string Main(){AssetDatabase.Refresh();foreach(var p in new[]{"Assets/Prefabs/Workshop/Services/LootTrader_Wooden_01.prefab","Assets/Prefabs/Workshop/Sheriff/Sheriff_Stone_Compact_01.prefab","Assets/Prefabs/Workshop/CastleServices/CastleServices_01.prefab"})if(AssetDatabase.LoadAssetAtPath<GameObject>(p)==null)throw new Exception("Prefab import failed "+p);var hs=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses");var probe=new GameObject("Temporary_Entry_Probe");try{var cc=probe.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;foreach(var n in new[]{"03_LootTrader","05_Nursery"}){var h=hs.Find(n);probe.transform.position=h.TransformPoint(new Vector3(0,.55f,-4.5f));Physics.SyncTransforms();for(int j=0;j<95;j++)cc.Move(h.TransformVector(new Vector3(0,0,.04f))+Vector3.down*.025f);var end=h.InverseTransformPoint(probe.transform.position);if(end.z<-1||!cc.isGrounded)throw new Exception("Entrance blocked "+n+" "+end);}}finally{UnityEngine.Object.DestroyImmediate(probe);}var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty)EditorSceneManager.SaveScene(scene);if(scene.isDirty)throw new Exception("Scene dirty");File.AppendAllText("Docs/assets/examples/TRADER_BOUNTY085_VALIDATION.txt","PASS: three updated prefabs imported; character controller enters trader and sheriff with new board/posts; scene IsDirty=false.\n");return "Import, entrances and saved scene PASS.";}}
